param([switch]$CompararVinculos, [ValidateSet("Ativos", "Pausados")][string]$ModoVinculos = "Ativos", [string]$Projeto = (Get-Location).Path, [switch]$NaoCompilar, [switch]$Verificar, [switch]$TestarApresentacao, [switch]$TestarLista, [switch]$CapturarLog, [switch]$TestarSeries, [string]$Emulador = "emulator-5554")
$ErrorActionPreference = 'Stop'
if ($ModoVinculos -eq 'Pausados' -and -not $CompararVinculos) { throw 'Modo pausado exige -CompararVinculos. Nao publique APKs de diagnostico.' }
if ($CompararVinculos) { $CapturarLog = $true }
elseif ($CapturarLog) { $TestarSeries = $true }
if (($CompararVinculos -or $TestarApresentacao -or $TestarSeries -or $TestarLista) -and $NaoCompilar) { throw 'Testes nativos exigem compilacao. Nada foi alterado.' }
if (($CompararVinculos -or $TestarApresentacao -or $TestarSeries -or $TestarLista) -and $Emulador -notmatch '^emulator-[0-9]+$') { throw 'Informe o ID de um emulador Android. Nada foi alterado.' }
$Projeto = [System.IO.Path]::GetFullPath($Projeto)
if (-not (Test-Path -LiteralPath (Join-Path $Projeto 'gradlew.bat'))) { throw 'Execute na raiz do projeto ou informe -Projeto.' }
$temp = Join-Path ([System.IO.Path]::GetTempPath()) ('IPTV-series-vinculos-' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $temp | Out-Null
